(function () {
  "use strict";
  var data = window.REDESIGN_DATA;
  var esc = function (value) { return String(value).replace(/[&<>"']/g, function (c) { return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]; }); };
  var num = function (value) { return Math.round(value * 10) / 10; };
  var pct = function (n, d) { return num(n * 100 / d); };
  var fmt = function (value) { return value.toLocaleString("en-US"); };
  var blue = "#24a8ff", white = "#f6f6f4", muted = "#7e7e7b";
  var text = function (x, y, value, size, fill, anchor) { return '<text x="'+x+'" y="'+y+'" font-size="'+size+'" fill="'+fill+'" text-anchor="'+(anchor||"start")+'">'+esc(value)+'</text>'; };
  var svg = function (id, body, title, viewBox) { return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="'+viewBox+'" role="img" aria-labelledby="'+id+'-title"><title id="'+id+'-title">'+esc(title)+'</title>'+body+'</svg>'; };
  var foot = function (label, index) { return '<footer class="scene-foot"><span>가상 '+label+' · 첫 경험 개선 프로젝트</span><a class="data-link" href="#data-'+['trend','funnel','matrix'][index-1]+'">수치 보기</a><span>'+index+' / 03</span></footer>'; };
  var periods = data.periods.map(function (period) { var weeks=data.weeklyCohorts.filter(function (w) { return w.week>=period.fromWeek&&w.week<=period.toWeek; }); return Object.assign({},period,{registered:weeks.reduce(function(s,w){return s+w.registered;},0),activated:weeks.reduce(function(s,w){return s+w.activated;},0)}); });
  var baseline=periods.find(function(p){return p.id==="baseline";}), followup=periods.find(function(p){return p.id==="followup";});
  var weeks=data.weeklyCohorts, first=weeks[0],last=weeks[weeks.length-1];
  var left=40, right=1190, top=15, bottom=285;
  var tx=function(index){return left+index/(weeks.length-1)*(right-left);};
  var ty=function(value){return bottom-value/100*(bottom-top);};
  var plot="";
  [0,50,100].forEach(function(tick){var y=ty(tick);plot+='<line x1="'+left+'" y1="'+y+'" x2="'+right+'" y2="'+y+'" stroke="'+(tick===0?'#555552':'#202020')+'" stroke-width="1"/>'+text(left-10,y+7,tick,18,muted,"end");});
  var points=weeks.map(function(w,i){return tx(i)+","+ty(pct(w.activated,w.registered));});
  plot+='<polyline points="'+points.join(" ")+'" fill="none" stroke="'+blue+'" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>';
  weeks.forEach(function(w,i){plot+='<circle cx="'+tx(i)+'" cy="'+ty(pct(w.activated,w.registered))+'" r="'+(i===weeks.length-1?7:3.5)+'" fill="'+blue+'"/>';});
  [0,weeks.length-1].concat(data.periods.slice(0,-1).map(function(p){return weeks.findIndex(function(w){return w.week===p.toWeek;});})).filter(function(v,i,a){return a.indexOf(v)===i;}).forEach(function(index){plot+=text(tx(index),320,"W"+weeks[index].week,20,muted,index===0?"start":index===weeks.length-1?"end":"middle");});
  plot+=text(tx(0),ty(pct(first.activated,first.registered))-16,pct(first.activated,first.registered)+"%",26,white);
  document.getElementById("trend").innerHTML='<header class="trend-head"><div><p class="eyebrow">주마다, 같은 관찰창으로</p><h2>첫 공유의 흐름을,<br>이어 봅니다.</h2><p class="context">가입 후 '+data.measurement.outcomeWindowDays+'일 안의 첫 공유율 · W'+first.week+'–W'+last.week+'</p></div><div class="hero-stat"><span class="value">'+pct(last.activated,last.registered)+'</span><span class="unit">%</span><p class="stat-caption">마지막 주 · 신규 가입 '+fmt(last.registered)+'명 중 '+fmt(last.activated)+'명</p></div></header><div class="trend-plot">'+svg("trend",plot,"주별 첫 공유율 추세. 첫 주 "+pct(first.activated,first.registered)+"%에서 마지막 주 "+pct(last.activated,last.registered)+"%.","0 0 1230 345")+'</div>'+foot("전후 관찰",1);
  var series=[baseline,followup].map(function(period){var mid=data.funnel.intermediateCounts.find(function(item){return item.period===period.id;});return data.funnel.stages.map(function(stage){return stage.source==="periodRegistered"?period.registered:stage.source==="periodActivated"?period.activated:mid[stage.id];});});
  var max=Math.max.apply(null,series[0].concat(series[1]));
  var rows=data.funnel.stages.map(function(stage,index){return '<div class="funnel-row '+(index===data.funnel.stages.length-1?'is-focus':'')+'"><div class="row-heading"><span class="funnel-label">'+esc(stage.label)+'</span><span class="funnel-values">'+fmt(series[0][index])+'<span class="arrow">→</span><strong>'+fmt(series[1][index])+'</strong></span></div><div class="bar-pair" aria-hidden="true"><i style="width:'+(series[0][index]/max*100)+'%"></i><i style="width:'+(series[1][index]/max*100)+'%"></i></div></div>';}).join("");
  document.getElementById("funnel").innerHTML='<div class="funnel-copy"><p class="eyebrow">처음에서, 첫 공유까지</p><h2>끝까지 간 사람을,<br>크게 봅니다.</h2><div class="funnel-stat"><span class="value">'+fmt(followup.activated)+'</span><span class="unit">명</span><p>기준 '+fmt(baseline.activated)+'명 → 후반 '+fmt(followup.activated)+'명</p></div><p class="context">각 기간 신규 가입 '+fmt(baseline.registered)+'명<br>가입 후 '+data.measurement.outcomeWindowDays+'일 이내</p></div><div class="funnel-plot">'+rows+'<div class="funnel-key"><span>기준 · W'+baseline.fromWeek+'–W'+baseline.toWeek+'</span><span>후반 · W'+followup.fromWeek+'–W'+followup.toWeek+'</span></div></div>'+foot("전후 관찰",2);
  var min=data.initiatives.scoreScale.min,maximum=data.initiatives.scoreScale.max;
  var px=function(v){return 65+(v-min)/(maximum-min)*1090;};
  var py=function(v){return 325-(v-min)/(maximum-min)*275;};
  var matrix="";
  [min,(min+maximum)/2,maximum].forEach(function(tick){if(tick!==maximum)matrix+='<line x1="65" y1="'+py(tick)+'" x2="1155" y2="'+py(tick)+'" stroke="'+(tick===min?'#454542':'#202020')+'"/>'+'<line x1="'+px(tick)+'" y1="50" x2="'+px(tick)+'" y2="325" stroke="'+(tick===min?'#454542':'#202020')+'"/>';matrix+=text(38,py(tick)+7,tick,20,muted,"end")+text(px(tick),365,tick,20,muted,"middle");});
  matrix+=text(65,30,"예상 영향 ↑",22,muted)+text(1155,410,"노력 →",22,muted,"end");
  var labels=[];
  data.initiatives.items.forEach(function(item,index){var x=px(item.effortScore),y=py(item.impactScore),active=index<2,color=active?blue:"#71716e";matrix+='<circle cx="'+x+'" cy="'+y+'" r="'+(active?10:7)+'" fill="'+color+'"/>';var anchor=x>900?"end":"start",labelX=x+(anchor==="end"?-22:22),width=Array.from(item.label).length*24;var candidates=[-22,44,-58,80];var offset=candidates.find(function(d){var box={x:anchor==="end"?labelX-width:labelX,y:y+d-26,w:width,h:32};return box.y>=0&&box.y+box.h<355&&!labels.some(function(b){return box.x<b.x+b.w&&box.x+box.w>b.x&&box.y<b.y+b.h&&box.y+box.h>b.y;});});if(offset===undefined)offset=44;var box={x:anchor==="end"?labelX-width:labelX,y:y+offset-26,w:width,h:32};labels.push(box);if(offset>0)matrix+='<line x1="'+x+'" y1="'+(y+12)+'" x2="'+labelX+'" y2="'+(y+offset-22)+'" stroke="'+color+'" stroke-width="1"/>';matrix+=text(labelX,y+offset,item.label,28,active?blue:white,anchor);});
  document.getElementById("matrix").innerHTML='<header class="matrix-head"><div><p class="eyebrow">다음에 할 일을 고릅니다</p><h2>무엇을 먼저,<br>확인할까요?</h2></div><p class="matrix-context">예상 영향 × 노력<br>가상 기획 판단 · '+min+'–'+maximum+'점</p></header><div class="matrix-plot">'+svg("matrix",matrix,"네 개선안의 영향과 노력 기획 점수. 이름은 각 점에 직접 연결됩니다.","0 0 1230 430")+'</div>'+foot("기획 판단",3);
  var table=function(id,title,heads,body){return '<section id="data-'+id+'"><h3>'+esc(title)+'</h3><div class="table-scroll" tabindex="0"><table><caption>'+esc(title)+'</caption><thead><tr>'+heads.map(function(h){return '<th scope="col">'+esc(h)+'</th>';}).join("")+'</tr></thead><tbody>'+body.map(function(row){return '<tr>'+row.map(function(cell,index){return index?'<td>'+esc(cell)+'</td>':'<th scope="row">'+esc(cell)+'</th>';}).join("")+'</tr>';}).join("")+'</tbody></table></div></section>';};
  document.getElementById("tables").innerHTML='<p>'+esc(data.meta.disclosure)+' '+esc(data.meta.studyDesign)+' '+esc(data.meta.reportingCutoff)+'</p>'+table("trend","주별 첫 공유율",["주차","신규 가입","7일 내 첫 공유","첫 공유율"],weeks.map(function(w){return ["W"+w.week,w.registered+"명",w.activated+"명",pct(w.activated,w.registered)+"%"]; }))+table("funnel","기간별 단계 인원",["단계","기준","후반"],data.funnel.stages.map(function(s,i){return [s.label,fmt(series[0][i])+"명",fmt(series[1][i])+"명"]; }))+table("matrix","기획 우선순위",["제안","영향","노력","기획 판단"],data.initiatives.items.map(function(item){return [item.label,item.impactScore,item.effortScore,item.priority];}));
  var current="trend";
  function select(id){current=id;document.querySelectorAll('.scene').forEach(function(scene){scene.classList.toggle('is-active',scene.id===id);});document.querySelectorAll('[data-scene]').forEach(function(button){button.setAttribute('aria-pressed',String(button.dataset.scene===id));});}
  document.querySelectorAll('[data-scene]').forEach(function(button){button.addEventListener('click',function(){select(button.dataset.scene);if(innerWidth<=700)document.getElementById(button.dataset.scene).scrollIntoView({behavior:'auto',block:'start'});});});
  document.querySelectorAll('.data-link').forEach(function(link){link.addEventListener('click',function(){document.querySelector('.reading-data').open=true;});});
  document.addEventListener('keydown',function(event){if(event.target.closest('input,textarea,select,.table-scroll,details')||event.altKey||event.metaKey||event.ctrlKey)return;var order=['trend','funnel','matrix'],index=order.indexOf(current);if(event.key==='ArrowRight'){event.preventDefault();select(order[Math.min(2,index+1)]);}if(event.key==='ArrowLeft'){event.preventDefault();select(order[Math.max(0,index-1)]);}});
  if(innerWidth<=700)document.querySelector('.reading-data').open=true;
})();
